JevDecision = {"method":"POST","url":"https://openrouter.ai/api/alpha/decisions","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"contentType":"json","specifyBody":"json","jsonBody":"={{ JSON.stringify($json.jev_request) }}","options":{"timeout":30000}};
